window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bbc808d9443291d2"]={"versions": [{"id": "FIG-bbc808d9443291d2", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion bei der Meldung flüchtiger Fehler (<em>Transient Faults</em>) im AUTOSAR-Classic-Plattform-Basissoffware-Modul <em>Default Error Tracer</em> (DET).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Det User</strong>: Aufrufer bzw. Quellmodul (Software-Komponente oder BSW-Modul).\n</li><li><strong>«module» Det</strong>: Default Error Tracer als zentrales Fehlererfassungsmodul der BSW.\n</li><li><strong>Integrator Code</strong>: Benutzerdefinierte Callout-Routinen des Systemintegrators.\n</li><li><strong>Notizfeld</strong>: <code>&lt;Det_General&gt; configured TransientFault callouts</code>.\n</li><li><strong>Schnittstellen</strong>:\n<ul class=\"fig-list\"><li><code>Det_ReportTransientFault(return, ModuleId, InstanceId, ApiId, FaultId)</code>: Synchroner Serviceaufruf zur Fehlermeldung.\n</li><li><code>&lt;Det_ReportTransientFaultCallout&gt;(return, ModuleId, InstanceId, ApiId, FaultId)</code>: Konfigurierbarer Callout an den Integrator-Code.\n</li><li><code>:X</code>: Rückgabewert des Callouts sowie des Serviceaufrufs.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Det User</code> sendet den synchronen Aufruf <code>Det_ReportTransientFault(return, ModuleId, InstanceId, ApiId, FaultId)</code> an <code>Det</code>.\n</li><li>Während der Ausführung ruft <code>Det</code> gemäß Konfiguration in <code>&lt;Det_General&gt;</code> den Callout <code>&lt;Det_ReportTransientFaultCallout&gt;(return, ModuleId, InstanceId, ApiId, FaultId)</code> an <code>Integrator Code</code> auf.\n</li><li><code>Integrator Code</code> schließt die Bearbeitung ab und liefert den Rückgabewert <code>:X</code> an <code>Det</code> zurück.\n</li><li><code>Det</code> reicht das Ergebnis <code>:X</code> als Antwort auf den ursprünglichen Serviceaufruf an <code>Det User</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Die Meldung von Transient Faults erfolgt synchron und blockierend über den Det.\n</li><li>Das Weiterleiten des Fehlers an anwenderspezifische Callouts hängt von der Konfiguration der Transient-Fault-Callouts im Container <code>&lt;Det_General&gt;</code> ab.\n</li><li>Der Rückgabewert des Integrator-Callouts bestimmt den Ergebniswert <code>:X</code>, der an den Aufrufer (<code>Det User</code>) zurückgemeldet wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5335eb1ab6a63b05", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion bei der Meldung flüchtiger Fehler (<em>Transient Faults</em>) im AUTOSAR-Classic-Plattform-Basissoffware-Modul <em>Default Error Tracer</em> (DET).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Det User</strong>: Aufrufer bzw. Quellmodul (Software-Komponente oder BSW-Modul).\n</li><li><strong>«module» Det</strong>: Default Error Tracer als zentrales Fehlererfassungsmodul der BSW.\n</li><li><strong>Integrator Code</strong>: Benutzerdefinierte Callout-Routinen des Systemintegrators.\n</li><li><strong>Notizfeld</strong>: <code>&lt;Det_Notification&gt; configured TransientFault callouts</code>.\n</li><li><strong>Schnittstellen</strong>:\n<ul class=\"fig-list\"><li><code>Det_ReportTransientFault(return, ModuleId, InstanceId, ApiId, FaultId)</code>: Synchroner Serviceaufruf zur Fehlermeldung.\n</li><li><code>&lt;Det_ReportTransientFaultCallout&gt;(return, ModuleId, InstanceId, ApiId, FaultId)</code>: Konfigurierbarer Callout an den Integrator-Code.\n</li><li><code>:X</code>: Rückgabewert des Callouts sowie des Serviceaufrufs.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Det User</code> sendet den synchronen Aufruf <code>Det_ReportTransientFault(return, ModuleId, InstanceId, ApiId, FaultId)</code> an <code>Det</code>.\n</li><li>Während der Ausführung ruft <code>Det</code> gemäß Konfiguration in <code>&lt;Det_Notification&gt;</code> den Callout <code>&lt;Det_ReportTransientFaultCallout&gt;(return, ModuleId, InstanceId, ApiId, FaultId)</code> an <code>Integrator Code</code> auf.\n</li><li><code>Integrator Code</code> schließt die Bearbeitung ab und liefert den Rückgabewert <code>:X</code> an <code>Det</code> zurück.\n</li><li><code>Det</code> reicht das Ergebnis <code>:X</code> als Antwort auf den ursprünglichen Serviceaufruf an <code>Det User</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Die Meldung von Transient Faults erfolgt synchron und blockierend über den Det.\n</li><li>Das Weiterleiten des Fehlers an anwenderspezifische Callouts hängt von der Konfiguration der Transient-Fault-Callouts im Container <code>&lt;Det_Notification&gt;</code> ab.\n</li><li>Der Rückgabewert des Integrator-Callouts bestimmt den Ergebniswert <code>:X</code>, der an den Aufrufer (<code>Det User</code>) zurückgemeldet wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8641318c9852049e", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion bei der Meldung flüchtiger Fehler (<em>Transient Faults</em>) im AUTOSAR-Classic-Plattform-Basissoffware-Modul <em>Default Error Tracer</em> (DET).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Det User</strong>: Aufrufer bzw. Quellmodul (Software-Komponente oder BSW-Modul).\n</li><li><strong>«module» Det</strong>: Default Error Tracer als zentrales Fehlererfassungsmodul der BSW.\n</li><li><strong>Integrator Code</strong>: Benutzerdefinierte Callout-Routinen des Systemintegrators.\n</li><li><strong>Notizfeld</strong>: <code>&lt;Det_Notification&gt; configured TransientFault callouts</code>.\n</li><li><strong>Schnittstellen</strong>:\n<ul class=\"fig-list\"><li><code>Det_ReportTransientFault(return, ModuleId, InstanceId, ApiId, FaultId)</code>: Synchroner Serviceaufruf zur Fehlermeldung.\n</li><li><code>&lt;Det_ReportTransientFaultCallout&gt;(return, ModuleId, InstanceId, ApiId, FaultId)</code>: Konfigurierbarer Callout an den Integrator-Code.\n</li><li><code>:X</code>: Rückgabewert des Callouts sowie des Serviceaufrufs.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Det User</code> sendet den synchronen Aufruf <code>Det_ReportTransientFault(return, ModuleId, InstanceId, ApiId, FaultId)</code> an <code>Det</code>.\n</li><li>Während der Ausführung ruft <code>Det</code> gemäß Konfiguration in <code>&lt;Det_Notification&gt;</code> den Callout <code>&lt;Det_ReportTransientFaultCallout&gt;(return, ModuleId, InstanceId, ApiId, FaultId)</code> an <code>Integrator Code</code> auf.\n</li><li><code>Integrator Code</code> schließt die Bearbeitung ab und liefert den Rückgabewert <code>:X</code> an <code>Det</code> zurück.\n</li><li><code>Det</code> reicht das Ergebnis <code>:X</code> als Antwort auf den ursprünglichen Serviceaufruf an <code>Det User</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Die Meldung von Transient Faults erfolgt synchron und blockierend über den Det.\n</li><li>Das Weiterleiten des Fehlers an anwenderspezifische Callouts hängt von der Konfiguration der Transient-Fault-Callouts im Container <code>&lt;Det_Notification&gt;</code> ab.\n</li><li>Der Rückgabewert des Integrator-Callouts bestimmt den Ergebniswert <code>:X</code>, der an den Aufrufer (<code>Det User</code>) zurückgemeldet wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-bbc808d9443291d2", "to": "FIG-5335eb1ab6a63b05", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Notiz am Det-Aktivierungsbalken: Konfigurationscontainer für konfigurierte TransientFault-Callouts von <code>&lt;Det_General&gt;</code> zu <code>&lt;Det_Notification&gt;</code> geändert.\n</li></ul>"}, {"from": "FIG-5335eb1ab6a63b05", "to": "FIG-8641318c9852049e", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
